   "q": "رحلة مصر: جوى أودى بقلبك أم وجيب . غداة غدابك الحادي الطروب. بعدت عن الديار وصرت تدعو . على البعد الديار ولا محيد. رحلت وأنت للعلياء صادٍ . عوم على الموارد أو تلوب. خلفت المنازل أنسات . يروب الفيد يتبعها سروب. سق حشاك من كلف علنها . وترضات وتأنف أن تشق لك الجيوب. بشد الرجل من بلد لأخرى . ومالمناك من بلد نصيب. وفي مصر أداك وأنت لاه . وقلبك في الفراق جوى يذوب. دع الأنفاس تصعد محرقات وخل الدمع من علق يصوب. لقد بان الخليط فلا خليط . وقد بعد الحبيب فلا حبيب. (يختار الطالب ثلاثة أبيات من القصيدة)",
