   "why": "أولاً: هو أول أنواع الشعر كتبت به البشرية ولجأ إليه الإنسان عندما فعل وأراد أن يعرب عن انفعاله بأي شيء كلامي يعبر عن الإحساس الشخصي للشاعر، وجاء أول الأمر بسيطاً وقد يُصحب بالرقص والموسيقا والغناء لذلك يسمى أيضاً (الشعر الغنائي)، ثم تطور هذا النوع فامتد من البيت والبيتين إلى المقطوعة فالقصيدة الطويلة، وكانت موضوعاتها الأولى فردية ذاتية تعبر عن ذات الشاعر ووجدانه. ثانياً: نشأت القصة القصيرة من أصل عربي تمثلت في السير والمقامات والقصص الحماسية والحكايات والأمثال والخرافات والأساطير والنوادر، وتأثرت بالأدب الأجنبي فقد تُرجمت أعداد كبيرة منها مع مطلع القرن العشرين عن لغات مختلفة، وكان بعض المترجمين يتصرفون في القصة، فيغيرون فيها بما يلائم مزاجهم أو يلائم البيئة العربية.",
