   "q": "أ/ الشاعر هو عبد المحسن الكاظمي، عنوان قصيدته (رحلة مصر)، اكتب الأبيات المطلوبة",
   "o": [],
   "c": -1,
   "why": "جوىً أودىٰ بقلبك أم وجيبُ ... غرامٌ ما بكَ الحادي الطروبُ أقفرتِ الديار ولا مجيبُ ... بَعُدتَ عن الديار وصرتَ توعو رحلت وأنتَ للعلياءِ صادٍ ... تحومُ علىٰ الموارد أو قلوبُ سروبُ الغير يتبعُها سروبُ ... وخلَّفتَ المنازلَ خاوياتٍ تَشُقُ مَشاقَّ من كلفٍ عليما ... وتأنفُ أن تُشُقَ لكَ الجيوبُ تشرُ الرحل من بلدٍ لأخرىٰ ... وما لِمُناك مِنْ بلدٍ نصيبُ وفي مصرِ أراكَ وأنتَ لاهٍ ... وقلبُكَ في العراقِ جوىً يؤوبُ ألا فاصبر مرتابٍ وَخلّ الدمعَ مِنْ علقٍ يعوبُ لقد بانَ الخليطُ فلا خليطٌ ... وقر بَعُدَ الحبيبُ فلا حبيبُ (ملاحظة: يختار الفاحص ثلاثة أبيات يكتبها الطالب وتُقبل).",
