   "c": -1,
   "why": "أولاً: تعد المقامة من الفنون العريقة في الأدب العربي، وهي تجمع بين سمات الحكاية الشعبية والقصة القصيرة والسيرة الذاتية، مضمنة الجد بالهزل ضمن أسلوب من السجع في صياغتها في كثير من الأحيان، مع توشيتها ببعض الأبيات الشعرية المناسبة، ومن المشاهير القدامى في هذا اللون النثري: بديع الزمان الهمذاني والحريري. ومن المحدثين: أبي الثناء الألوسي في العراق والمويلحي في مصر. ثانياً: نشأت المقالة الحديثة في الآداب الأوربية وارتبطت نشأتها بالصحافة، ويعد الكاتب الفرنسي مونتيني منشئ المقالة الحديثة. وقد عرف أدبنا القديم فناً أدبياً شبيهاً بالمقالة هو (فن الرسائل).",
