   "why": "(أولاً) طرق شعراء المهجر موضوعات الحياة الجديدة المستقاة من الإنسان والحياة والطبيعة، فكان لديهم الشعر التأملي الفلسفي والشعر الاجتماعي الذين عبروا عن طريقته بحرارة عما تعيش فيه أمتهم حاملين همومها وقضاياها في قصيدتهم، أما في الشكل فقد غيروا في الأوزان بطرائق متعددة وواسعة وجعلوا للقصيدة الواحدة أوزاناً مختلفة أسموها (مجمع البحور) وهو ما لم يألفه الشعر العربي كثيراً. (ثانياً) هو نوع إبداعي جديد شاع في أدبنا المعاصر تبناه عدد من الشعراء منذ السبعينات من القرن الماضي ومازال وتعود جذوره إلى نهاية الستينات وبداية السبعينات، ويتميز هذا النوع باللغة الشعرية المكثفة والصور الشعرية الطريفة والأسلوب المركز مع إحلال قيمة إيقاعية جديدة لا علاقة لها بالتفعيلات التراثية.",
